alter table public.timeline_daw_private_audio_lanes add column if not exists stretch_ratio double precision not null default 1 check(stretch_ratio between .25 and 4),add column if not exists pitch_semitones double precision not null default 0 check(pitch_semitones between -24 and 24),add column if not exists transform_algorithm text not null default 'preserve-pitch' check(transform_algorithm in('preserve-pitch','resample')),add column if not exists transform_bypassed boolean not null default false;
alter table public.timeline_daw_private_lane_edit_history drop constraint if exists timeline_daw_private_lane_edit_history_operation_check;
alter table public.timeline_daw_private_lane_edit_history add constraint timeline_daw_private_lane_edit_history_operation_check check(operation in('arrange','split','duplicate','fade','remove','group','transform'));
